INSERT INTO flows (
  id, tenant_id, client_id, profile_id, name, description, graph_definition,
  compiled_plan, version, is_active, is_builtin, created_by, created_at, updated_by,
  updated_at, slug, display_name, kind, status, draft_editor_json, draft_runtime_base_json,
  published_version_id, deleted_at, template_id
)
SELECT
  'flow-builtin-shared-default-login', 'default', NULL, 'human-basic',
  'Shared Login', 'Built-in reference Flow for Direct, OIDC, and SAML login.',
  editor_json, runtime_json, '1.0.0', TRUE, TRUE, 'system', __AUTHRIM_NOW_EPOCH_SECONDS__,
  'system', __AUTHRIM_NOW_EPOCH_SECONDS__, 'shared-default-login', 'Shared Login',
  'login', 'published', editor_json, runtime_json,
  'flow-version-builtin-shared-default-login-v1', NULL, 'default-login'
FROM builtin
WHERE NOT EXISTS (
  SELECT 1 FROM flows
  WHERE tenant_id = 'default'
    AND (id = 'flow-builtin-shared-default-login'
      OR (slug = 'shared-default-login' AND deleted_at IS NULL))
);

INSERT INTO flow_versions (
  id, tenant_id, flow_id, version_number, schema_version, runtime_snapshot_json,
  editor_snapshot_json, validation_result_json, published_by, published_at, created_at
)
SELECT
  'flow-version-builtin-shared-default-login-v1', 'default',
  'flow-builtin-shared-default-login', 1, 'authrim.login_ui.contract.v1',
  draft_runtime_base_json, draft_editor_json,
  '{"valid":true,"errors":[],"warnings":[],"issues":[]}',
  'system', __AUTHRIM_NOW_EPOCH_SECONDS__, __AUTHRIM_NOW_EPOCH_SECONDS__
FROM flows
WHERE tenant_id = 'default' AND id = 'flow-builtin-shared-default-login'
  AND NOT EXISTS (
    SELECT 1 FROM flow_versions
    WHERE tenant_id = 'default' AND id = 'flow-version-builtin-shared-default-login-v1'
  );
